#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>
#include "bf_target_obligation.h"
#include "inverse_programs.h"
typedef struct{char contract[512],policy[96],predicate_id[128],owner[96],predicate[128],expected[64],evidence[256],authority[256],valid_start[64],valid_end[64];}ProposalContract;
static const char *opt(int ac,char **av,const char *name){for(int i=2;i+1<ac;i++)if(!strcmp(av[i],name))return av[i+1];return NULL;}
static int text_ok(const char*s){if(!s||!*s)return 0;for(;*s;s++)if(*s=='"'||*s=='\\'||*s=='\n'||*s=='\r')return 0;return 1;}
static const BfInverseOwnerGrammar *grammar(const char*o,const char*p,const char*e){for(size_t i=0;i<bf_inverse_owner_grammar_count;i++){const BfInverseOwnerGrammar*g=&bf_inverse_owner_grammar[i];if(!strcmp(g->owner,o)&&!strcmp(g->predicate,p)&&!strcmp(g->expected,e))return g;}return NULL;}
static void col(sqlite3_stmt*s,int i,char*out,size_t n){const char*v=(const char*)sqlite3_column_text(s,i);snprintf(out,n,"%s",v?v:"");}
static int load_contract(const char*db,const char*operation,ProposalContract*c){sqlite3*d=0;sqlite3_stmt*s=0;int ok=0;if(!text_ok(db)||!text_ok(operation)||sqlite3_open_v2(db,&d,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)return 0;if(sqlite3_prepare_v2(d,"SELECT semantic_contract,preference_policy,predicate_id,owner,predicate,expected_state,COALESCE(evidence_requirement,''),COALESCE(authority_requirement,''),COALESCE(valid_start,''),COALESCE(valid_end,'') FROM proposal_contract WHERE operation=?1 AND status='published' ORDER BY id LIMIT 1",-1,&s,0)==SQLITE_OK){sqlite3_bind_text(s,1,operation,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW){memset(c,0,sizeof(*c));col(s,0,c->contract,sizeof(c->contract));col(s,1,c->policy,sizeof(c->policy));col(s,2,c->predicate_id,sizeof(c->predicate_id));col(s,3,c->owner,sizeof(c->owner));col(s,4,c->predicate,sizeof(c->predicate));col(s,5,c->expected,sizeof(c->expected));col(s,6,c->evidence,sizeof(c->evidence));col(s,7,c->authority,sizeof(c->authority));col(s,8,c->valid_start,sizeof(c->valid_start));col(s,9,c->valid_end,sizeof(c->valid_end));ok=1;}}if(s)sqlite3_finalize(s);sqlite3_close(d);return ok;}
static int persist(const char*db,const char*target_id,const char*target,const char*subject,const char*contract,const char*frontier,const char*policy,const char*predicate_id,const char*owner,const char*predicate,const char*expected,const char*evidence,const char*authority,const char*valid_start,const char*valid_end,const char*operation){const BfInverseOwnerGrammar*g;BfTargetObligation*store=0;BfTargetObligationRecord r;BfTargetPredicateRecord*rows=0;size_t count=0;BfTargetObligationSpec spec;BfTargetPredicateSpec ps;if(!text_ok(db)||!text_ok(target_id)||!text_ok(target)||!text_ok(subject)||!text_ok(contract)||!text_ok(frontier)||!text_ok(policy)||!text_ok(predicate_id)||!text_ok(owner)||!text_ok(predicate)||!text_ok(expected))return 2;g=grammar(owner,predicate,expected);if(!g)return 3;memset(&spec,0,sizeof spec);spec.target_id=target_id;spec.target=target;spec.semantic_contract=contract;spec.source_frontier=frontier;spec.preference_policy=policy;memset(&ps,0,sizeof ps);ps.predicate_id=predicate_id;ps.owner=owner;ps.subject=subject;ps.predicate=predicate;ps.expected_state=expected;ps.valid_start=valid_start?valid_start:"";ps.valid_end=valid_end?valid_end:"";ps.evidence_requirement=evidence?evidence:"";ps.authority_requirement=authority?authority:"";ps.adapter=g->adapter;ps.native_state=g->native_state;ps.owner_query=g->owner_query;if(bf_target_obligation_open(db,&store,stderr))return 4;if(bf_target_obligation_require(store,&spec,&ps,1)){bf_target_obligation_close(store);return 5;}if(bf_target_obligation_get(store,target_id,&r)||bf_target_obligation_list_predicates(store,target_id,&rows,&count)||count!=1){bf_target_obligation_close(store);return 6;}printf("{\"schema\":\"bonfyre-semantic-operation-receipt.v2\",\"birth_mode\":\"PROPOSE\",\"operation\":\"%s\",\"operation_lowering\":\"SemanticOperation->TargetObligation\",\"target_id\":\"%s\",\"target\":\"%s\",\"predicate_subject\":\"%s\",\"semantic_contract\":\"%s\",\"source_frontier\":\"%s\",\"state\":\"%s\",\"predicate\":{\"owner\":\"%s\",\"predicate\":\"%s\",\"expected\":\"%s\",\"adapter\":%u,\"native_state\":%u,\"owner_query\":%u},\"truth\":\"proposal_is_persistent_purpose_not_authority_proof_work_or_effect\"}\n",operation?operation:"",r.target_id,r.target,rows[0].subject,r.semantic_contract,r.source_frontier,bf_target_obligation_state_name(r.state),rows[0].owner,rows[0].predicate,rows[0].expected_state,(unsigned)rows[0].adapter,(unsigned)rows[0].native_state,(unsigned)rows[0].owner_query);bf_target_obligation_free_predicates(rows);bf_target_obligation_close(store);return 0;}
int main(int ac,char**av){const char*db,*target_id,*target,*subject,*frontier;if(ac<2)return 2;db=opt(ac,av,"--db");target_id=opt(ac,av,"--target-id");target=opt(ac,av,"--target");subject=opt(ac,av,"--subject");frontier=opt(ac,av,"--frontier");if(!strcmp(av[1],"propose-contract")){ProposalContract c;const char*cms=opt(ac,av,"--cms-db"),*operation=opt(ac,av,"--operation");if(!load_contract(cms,operation,&c)){fprintf(stderr,"semantic-operation: no published proposal contract\n");return 3;}return persist(db,target_id,target,subject,c.contract,frontier,c.policy,c.predicate_id,c.owner,c.predicate,c.expected,c.evidence,c.authority,c.valid_start,c.valid_end,operation);}if(!strcmp(av[1],"propose"))return persist(db,target_id,target,subject,opt(ac,av,"--contract"),frontier,opt(ac,av,"--policy"),opt(ac,av,"--predicate-id"),opt(ac,av,"--owner"),opt(ac,av,"--predicate"),opt(ac,av,"--expected"),opt(ac,av,"--evidence"),opt(ac,av,"--authority"),opt(ac,av,"--valid-start"),opt(ac,av,"--valid-end"),"internal");fprintf(stderr,"usage: bonfyre-semantic-operation propose[-contract] ...\n");return 2;}
